def mark_existing_checkouts_unclassified(apps, schema_editor):
    # An old open Checkout can mean everyday use or a temporary loan. The
    # migration must not guess, nor create a physical return to clear it. Closed
    # legacy rows also have no proven temporary purpose.
    Checkout = apps.get_model('assets', 'AssetCheckout')
    existing = Checkout.objects.using(schema_editor.connection.alias)
    existing.update(classification='Unknown')
    existing.filter(status='Open').update(
        classification='Unclassified')


